//! `GEO.COVER` and `GEO.COVER.RL`.
//! The expectations are the answers of Warp 10 3.5.0 to the same scripts:
//! the JSON stack (top first) or the error message (in its JDK 11+ form).

use crate::tests::test_stack;
use crate::value::Value;

const ONE: &str = r"NEWGTS 1 48.85 2.35 NaN 1 ADDVALUE";
const TWO: &str = r"NEWGTS 1 48.85 2.35 NaN 1 ADDVALUE 2 48.9 2.4 NaN 2 ADDVALUE";
const FAR: &str = r"NEWGTS 1 48.85 2.35 NaN 1 ADDVALUE 2 -33.9 151.2 NaN 2 ADDVALUE 3 89.99 -179.99 NaN 3 ADDVALUE";
const GAPS: &str = r"NEWGTS 1 48.85 2.35 NaN 1 ADDVALUE 2 NaN NaN NaN 2 ADDVALUE 3 48.86 2.36 NaN 3 ADDVALUE 4 48.85 2.35 NaN 4 ADDVALUE";
const NOLOC: &str = r"NEWGTS 1 NaN NaN NaN 1 ADDVALUE 2 NaN NaN NaN 2 ADDVALUE";
const UNSORTED: &str =
    r"NEWGTS 5 49 3 NaN 5 ADDVALUE 1 48.85 2.35 NaN 1 ADDVALUE 3 48 2 NaN 3 ADDVALUE";
const E1: &str = r"NEWENCODER 1 48.85 2.35 NaN 1 ADDVALUE";
const E2: &str = r"NEWENCODER 1 48.85 2.35 NaN 1 ADDVALUE 2 48.9 2.4 NaN 2 ADDVALUE";
const EGAPS: &str =
    r"NEWENCODER 1 48.85 2.35 NaN 1 ADDVALUE 2 NaN NaN NaN 2 ADDVALUE 3 48.86 2.36 NaN 3 ADDVALUE";
const EUNSORTED: &str =
    r"NEWENCODER 5 49 3 NaN 5 ADDVALUE 1 48.85 2.35 NaN 1 ADDVALUE 3 48 2 NaN 3 ADDVALUE";
const EMPTYE: &str = r"NEWENCODER";

/// The script of a template, its `@NAME` placeholders replaced by the series above.
fn expand(template: &str) -> String {
    template
        .replace("@EUNSORTED", EUNSORTED)
        .replace("@UNSORTED", UNSORTED)
        .replace("@EMPTYE", EMPTYE)
        .replace("@NOLOC", NOLOC)
        .replace("@EGAPS", EGAPS)
        .replace("@GAPS", GAPS)
        .replace("@ONE", ONE)
        .replace("@TWO", TWO)
        .replace("@FAR", FAR)
        .replace("@E1", E1)
        .replace("@E2", E2)
}

/// The stack left by `script`, top first, as the JSON array of the Warp 10 exec endpoint,
/// or the error message.
fn stack_json(script: &str) -> Result<String, String> {
    let mut stack = test_stack();
    stack
        .exec_checked(&format!("{script} DEPTH ->LIST REVERSE ->JSON"))
        .map_err(|err| err.to_string())?;
    match stack.pop().expect("pop should succeed") {
        Value::String(json) => Ok(json.to_string()),
        other => panic!("not a string: {other:?}"),
    }
}

/// Check every case, reporting all the mismatches at once.
fn check(cases: &[(&str, Result<&str, &str>)]) {
    let mut failures = Vec::new();
    for (template, expected) in cases {
        let script = expand(template);
        match (expected, stack_json(&script)) {
            (Ok(json), Ok(actual)) if actual == *json => {}
            (Err(message), Err(actual)) if actual.contains(message) => {}
            (expected, actual) => failures.push(format!(
                "{template}\n  expected {expected:?}\n  actual   {actual:?}"
            )),
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

