#[test]
fn cover_1() {
    check(&[
        (r"[ ] 10 GEO.COVER", Ok(r"[[]]")),
        (r"[ ] 10 GEO.COVER SIZE", Ok(r"[0]")),
        (
            r"@UNSORTED 10 GEO.COVER DROP @UNSORTED TICKLIST",
            Ok(r"[[5,1,3]]"),
        ),
        (
            r"@ONE 1 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 0 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE -2 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 3 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 31 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 32 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 34 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 4294967298 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 4.0 GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE 'a' GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE NULL GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (
            r"@ONE [ 4 ] GEO.COVER",
            Err(r"GEO.COVER expects a resolution (even number from 2 to 30)."),
        ),
        (r"10 GEO.COVER", Err(r"Empty stack.")),
        (r"GEO.COVER", Err(r"Empty stack.")),
        (
            r"'a' 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"NULL 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"T 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"1 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"[ 1 ] 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"[ @ONE 1 ] 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"[ @ONE 'a' ] 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"{ 'a' 1 } 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"[ [ @ONE ] ] 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
        (
            r"@ONE 10 GEO.COVER 10 GEO.COVER",
            Err(r"GEO.COVER can only operate on Geo Time Series or GTS Encoders."),
        ),
    ]);
}

